:root {
  --card-bg: #fdf6e3;
  --card-border: #b89a5e;
  --header-bg: #4a3b1f;
  --header-text: #fdf0c8;
  --batch-text: #c8a96e;
  --label-text: #7a5c2e;
  --value-text: #2e1f0a;
  --footer-bg: #ede0c4;
  --footer-border: #c4a96a;
  --swatch-pale: #f5e8a0;
  --swatch-mid: #d4b840;
  --swatch-deep: #a07c10;
  --swatch-dark: #5c430a;
  --swatch-border: #b89a5e;
  --cell-border: #d4bc88;
  --notes-label: #7a5c2e;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
}

.dye-card {
  background: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 6px;
  width: 460px;
  overflow: hidden;
}

.card-header {
  background: var(--header-bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 16px;
}

.studio-label {
  color: var(--header-text);
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.batch-id {
  color: var(--batch-text);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
}

.swatch-row {
  display: flex;
  gap: 0;
  padding: 16px 16px 10px;
  justify-content: center;
  gap: 12px;
}

.swatch {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  margin: 0;
}

.swatch-block {
  width: 72px;
  height: 48px;
  border-radius: 4px;
  border: 1.5px solid var(--swatch-border);
}

.swatch[data-shade="light"] .swatch-block {
  background: var(--swatch-pale);
}

.swatch[data-shade="mid"] .swatch-block {
  background: var(--swatch-mid);
}

.swatch[data-shade="deep"] .swatch-block {
  background: var(--swatch-deep);
}

.swatch[data-shade="dark"] .swatch-block {
  background: var(--swatch-dark);
}

.swatch figcaption {
  font-size: 11px;
  color: var(--label-text);
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  border-top: 1px solid var(--cell-border);
  border-left: 1px solid var(--cell-border);
  margin: 10px 16px;
  border-radius: 4px;
  overflow: hidden;
}

.info-cell {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 10px;
  border-right: 1px solid var(--cell-border);
  border-bottom: 1px solid var(--cell-border);
}

.info-label {
  font-size: 10px;
  font-weight: 700;
  color: var(--label-text);
  text-transform: uppercase;
  letter-spacing: 0.07em;
}

.info-value {
  font-size: 13px;
  font-weight: 500;
  color: var(--value-text);
}

.card-footer {
  background: var(--footer-bg);
  border-top: 1px solid var(--footer-border);
  display: flex;
  align-items: baseline;
  gap: 6px;
  padding: 8px 16px;
}

.notes-label {
  font-size: 11px;
  font-weight: 700;
  color: var(--notes-label);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  flex-shrink: 0;
}

.notes-text {
  font-size: 12px;
  color: var(--value-text);
}
